package foodchain

import "strings"

var animals = []string{
	"fly",
	"spider",
	"bird",
	"cat",
	"dog",
	"goat",
	"cow",
	"horse",
}

var comments = []string{
	"I don't know why she swallowed the fly. Perhaps she'll die.",
	"It wriggled and jiggled and tickled inside her.",
	"How absurd to swallow a bird!",
	"Imagine that, to swallow a cat!",
	"What a hog, to swallow a dog!",
	"Just opened her throat and swallowed a goat!",
	"I don't know how she swallowed a cow!",
	"She's dead, of course!",
}

var spiderDetail = " that wriggled and jiggled and tickled inside her"

// Verse returns the lyrics of the verse for the given animal number (1-8).
func Verse(v int) string {
	var b strings.Builder
	b.WriteString("I know an old lady who swallowed a ")
	b.WriteString(animals[v-1])
	b.WriteString(".\n")
	b.WriteString(comments[v-1])
	if v == len(animals) {
		return b.String()
	}
	for i := v - 1; i >= 0; i-- {
		b.WriteString("\nShe swallowed the ")
		b.WriteString(animals[i])
		b.WriteString(" to catch the ")
		b.WriteString(animals[i-1])
		if i-1 == 1 {
			b.WriteString(spiderDetail)
		}
		b.WriteString(".")
	}
	return b.String()
}

// Verses returns the lyrics of verses from start to end, inclusive.
func Verses(start, end int) string {
	verses := make([]string, 0, end-start+1)
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

// Song returns the complete song.
func Song() string {
	return Verses(1, len(animals))
}

